-- +goose Up
-- Built-in fictional teaching data only. No scan results or human labels are changed.
CREATE TABLE public.synthetic_training_datasets (
  id text PRIMARY KEY,
  payload jsonb NOT NULL CHECK (
    payload->>'dataset_kind'='synthetic' AND payload->>'id'=id
    AND jsonb_typeof(payload->'samples')='array'
    AND jsonb_array_length(payload->'samples') > 0
  ),
  created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.synthetic_training_datasets ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.synthetic_training_datasets FORCE ROW LEVEL SECURITY;
REVOKE ALL ON public.synthetic_training_datasets FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.synthetic_training_datasets TO authenticated;
-- These immutable, fictional samples are shared with signed-in users.
CREATE POLICY synthetic_training_datasets_read ON public.synthetic_training_datasets
  FOR SELECT TO authenticated USING ((SELECT auth.uid()) IS NOT NULL);
